    // 1. Null checks
    if ((c == NULL) || (body == NULL) || (reference == NULL) || 
        (innovation == NULL) || (angle == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Finite checks for input vectors
    if (!adcs_is_finite_vec3(body) || !adcs_is_finite_vec3(reference)) {
        innovation->x = 0.0;
        innovation->y = 0.0;
        innovation->z = 0.0;
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t b;
    // 3. Normalize body vector: b = normalize(body)
    if (adcs_vec3_normalize(body, ADCS_EPS_NORM, &b) != ADCS_OK) {
        innovation->x = 0.0;
        innovation->y = 0.0;
        innovation->z = 0.0;
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t ref_norm;
    // 4. Normalize reference vector: ref_norm = normalize(reference)
    if (adcs_vec3_normalize(reference, ADCS_EPS_NORM, &ref_norm) != ADCS_OK) {
        innovation->x = 0.0;
        innovation->y = 0.0;
        innovation->z = 0.0;
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t mapped;
    // 5. Map inertial reference to body frame: temp = C_BI * ref_norm
    mapped = adcs_mat3_mul_vec(c, &ref_norm);

    adcs_vec3_t p;
    // 6. Normalize mapped vector: p = normalize(temp)
    if (adcs_vec3_normalize(&mapped, ADCS_EPS_NORM, &p) != ADCS_OK) {
        innovation->x = 0.0;
        innovation->y = 0.0;
        innovation->z = 0.0;
        *angle = INFINITY;
        return ADCS_E_RANGE;
    }

    // 7. Compute innovation: b cross p
    *innovation = adcs_vec3_cross(&b, &p);

    // 8. Compute angle: atan2(||innovation||, clamp(b dot p, -1, 1))
    double dot_val = adcs_vec3_dot(&b, &p);
    double clamped_dot = ADCS_CLAMP(dot_val, -1.0, 1.0);
    double cross_norm = adcs_vec3_norm(innovation);

    *angle = atan2(cross_norm, clamped_dot);

    return ADCS_OK;
}

